+"use client";
+
+import { useEffect, useRef } from "react";
+
+type EditorCopy = {
+  toolbar: string;
+  bold: string;
+  italic: string;
+  underline: string;
+  bulleted: string;
+  numbered: string;
+  clear: string;
+};
+
+const commands = (copy: EditorCopy) => [
+  { command: "bold", text: "B", caption: copy.bold, className: "font-bold" },
+  { command: "italic", text: "I", caption: copy.italic, className: "italic font-medium" },
+  { command: "underline", text: "U", caption: copy.underline, className: "underline" },
+  { command: "insertUnorderedList", text: "•", caption: copy.bulleted, className: "text-lg leading-none" },
+  { command: "insertOrderedList", text: "1.", caption: copy.numbered, className: "text-xs font-semibold" },
+  { command: "removeFormat", text: "✕", caption: copy.clear, className: "text-xs" },
+];
+
+type Props = {
+  id: string;
+  label: string;
+  placeholder: string;
+  copy: EditorCopy;
+  value: string;
+  onChange: (html: string) => void;
+};
+
+export function RichTextEditor({ id, label, placeholder, copy, value, onChange }: Props) {
+  const editor = useRef<HTMLDivElement>(null);
+
+  // Seed the field once. Leaving it uncontrolled keeps the caret where the writer
+  // expects it instead of resetting it on every render.
+  useEffect(() => {
+    if (editor.current && editor.current.innerHTML !== value) editor.current.innerHTML = value;
+    // eslint-disable-next-line react-hooks/exhaustive-deps
+  }, []);
+
+  function sync() {
+    onChange(editor.current?.innerHTML ?? "");
+  }
+
+  function run(command: string) {
+    editor.current?.focus();
+    // execCommand is deprecated, but it is still the only dependency-free way to
+    // apply formatting inside a contenteditable field, and every current browser supports it.
+    document.execCommand(command, false);
+    sync();
+  }
+
+  // Paste as plain text so foreign markup never reaches the stored message.
+  function paste(event: React.ClipboardEvent<HTMLDivElement>) {
+    event.preventDefault();
+    document.execCommand("insertText", false, event.clipboardData.getData("text/plain"));
+    sync();
+  }
+
+  return (
+    <div>
+      <label className="text-[11px] font-semibold tracking-[.18em] text-[#72726d]" htmlFor={id}>{label}</label>
+      <div className="mt-2 border border-[#bdbdb7] focus-within:border-[#1b1b1b]">
+        <div role="toolbar" aria-label={copy.toolbar} className="flex flex-wrap items-center gap-1 border-b border-[#e2e0d9] bg-[#f7f4eb] px-2 py-1.5">
+          {commands(copy).map((item) => (
+            <button
+              key={item.command}
+              type="button"
+              title={item.caption}
+              aria-label={item.caption}
+              onMouseDown={(event) => event.preventDefault()}
+              onClick={() => run(item.command)}
+              className={`flex h-8 min-w-8 items-center justify-center border border-[#dedcd4] bg-white px-2 text-[#1b1b1b] transition hover:border-[#1b1b1b] hover:bg-[#f2d600] ${item.className}`}
+            >
+              <span aria-hidden="true">{item.text}</span>
+            </button>
+          ))}
+        </div>
+        <div
+          id={id}
+          ref={editor}
+          contentEditable
+          suppressContentEditableWarning
+          role="textbox"
+          aria-multiline="true"
+          aria-label={label}
+          data-placeholder={placeholder}
+          onInput={sync}
+          onPaste={paste}
+          className="rich-editor rich-content min-h-44 w-full px-3 py-3 text-base leading-7 outline-none"
+        />
+      </div>
+    </div>
+  );
+}
